import type { CalendarDate, CalendarDefinition, DateStyle, LeapCycle } from "@/lib/bindings";

// A TypeScript port of the Rust calendar module (to_date / from_date / format),
// so tick labels and date editors need no round trip to the backend. Golden
// fixtures generated by the Rust tests (calendar-fixtures.json) keep the two in
// lockstep, so change both sides together.
//
// Vocabulary:
// - "day" is the world's absolute day number (shared by every calendar).
// - "local" is `day - epochOffset`: the day counted from this calendar's year 1.
// - "year index" `a` is 0 for the year containing local day 0, -1 before it...
//   The displayed year number is `a + 1` in the first era, and restarts at 1
//   for every later era.
// Day numbers are plain JS numbers (exact up to 2^53; worlds stay within 10^12).

/** Division rounding towards negative infinity, corrected for float error. */
export function floorDiv(a: number, b: number): number {
  let q = Math.floor(a / b);
  // Float division can land one off for huge numerators; fix it up exactly.
  const r = a - q * b;
  if (r < 0) q -= 1;
  else if (r >= b) q += 1;
  return q;
}

/** Remainder that is never negative (JS `%` keeps the sign of the dividend). */
export function euclidMod(a: number, b: number): number {
  return ((a % b) + b) % b;
}

/** Days in a year without any leap day: the sum of all month lengths. */
export function daysPerYear(def: CalendarDefinition): number {
  return def.months.reduce((sum, m) => sum + m.days, 0);
}

export function epochOffsetOf(def: CalendarDefinition): number {
  return def.epochOffset ?? 0;
}

function extraDaysOf(def: CalendarDefinition): number {
  return def.leap?.extraDays ?? 0;
}

/** Whether year index `a` is a leap year (the largest cycle dividing `a + 1` decides). */
export function isLeapYear(def: CalendarDefinition, a: number): boolean {
  const rules: LeapCycle[] = def.leap?.rules ?? [];
  const y = a + 1;
  for (let i = rules.length - 1; i >= 0; i--) {
    const rule = rules[i];
    if (rule && euclidMod(y, rule.every) === 0) return rule.add;
  }
  return false;
}

/** Number of leap years among years 1..n (negative n counts backwards, as a negative number). */
function leapYearsUpTo(def: CalendarDefinition, n: number): number {
  const rules = def.leap?.rules ?? [];
  let total = 0;
  rules.forEach((rule, i) => {
    if (!rule.add) return;
    const next = rules[i + 1];
    total += floorDiv(n, rule.every) - (next ? floorDiv(n, next.every) : 0);
  });
  return total;
}

/** Days from local day 0 to the start of year index `a` (negative before year 0). */
export function daysBeforeYear(def: CalendarDefinition, a: number): number {
  return a * daysPerYear(def) + extraDaysOf(def) * leapYearsUpTo(def, a);
}

/** Days in year index `a`, leap day included. */
export function daysInYear(def: CalendarDefinition, a: number): number {
  return daysPerYear(def) + (isLeapYear(def, a) ? extraDaysOf(def) : 0);
}

/** Days in a month (`month` is 1-based) of year index `a`. */
export function daysInMonth(def: CalendarDefinition, a: number, month: number): number {
  const base = def.months[month - 1]?.days ?? 0;
  const leapMonth = def.leap && def.leap.monthIndex === month - 1 && isLeapYear(def, a);
  return base + (leapMonth ? extraDaysOf(def) : 0);
}

/** Day-of-year (0-based) on which a month (0-based index) starts in year index `a`. */
export function monthStartOffset(def: CalendarDefinition, a: number, monthIndex: number): number {
  let offset = 0;
  for (let i = 0; i < monthIndex; i++) offset += def.months[i]?.days ?? 0;
  if (def.leap && def.leap.monthIndex < monthIndex && isLeapYear(def, a)) {
    offset += def.leap.extraDays;
  }
  return offset;
}

/** Year index containing a local day (the largest `a` whose year starts on or before it). */
export function yearIndexOf(def: CalendarDefinition, local: number): number {
  const base = daysPerYear(def);
  if (base <= 0) return 0;
  const extra = def.leap && def.leap.rules.some((r) => r.add) ? extraDaysOf(def) : 0;
  // Bounds that always bracket the answer, then an ordinary binary search.
  let lo: number;
  let hi: number;
  if (local >= 0) {
    lo = floorDiv(local, base + extra);
    hi = floorDiv(local, base) + 1;
  } else {
    lo = floorDiv(local, base);
    hi = 0;
  }
  while (lo < hi) {
    const mid = lo + floorDiv(hi - lo + 1, 2);
    if (daysBeforeYear(def, mid) <= local) lo = mid;
    else hi = mid - 1;
  }
  return lo;
}

/** Absolute day on which year index `a` starts. */
export function startOfYear(def: CalendarDefinition, a: number): number {
  return epochOffsetOf(def) + daysBeforeYear(def, a);
}

/** Absolute day on which a month (0-based index) of year index `a` starts. */
export function startOfMonth(def: CalendarDefinition, a: number, monthIndex: number): number {
  return startOfYear(def, a) + monthStartOffset(def, a, monthIndex);
}

/** Year index containing an absolute day. */
export function yearIndexOfDay(def: CalendarDefinition, day: number): number {
  return yearIndexOf(def, day - epochOffsetOf(def));
}

/** Index of the era a day falls in: the last era starting on or before it (else the first). */
export function eraIndexFor(def: CalendarDefinition, day: number): number {
  let index = 0;
  def.eras.forEach((era, i) => {
    if (era.startDay <= day) index = i;
  });
  return index;
}

/** Year index of the first year of an era (the year containing its start day). */
function eraStartYearIndex(def: CalendarDefinition, eraIndex: number): number {
  const era = def.eras[eraIndex];
  return era ? yearIndexOfDay(def, era.startDay) : 0;
}

/** Year index for a displayed `year` within an era (the inverse of the year in `toDate`). */
export function yearIndexFor(def: CalendarDefinition, eraIndex: number, year: number): number {
  return year - 1 + eraStartYearIndex(def, eraIndex);
}

export function eraLabel(def: CalendarDefinition, eraIndex: number): string {
  const era = def.eras[eraIndex];
  return era ? (era.abbreviation ?? era.name) : "";
}

/** Absolute day number -> calendar date (the same shape the backend returns). */
export function toDate(def: CalendarDefinition, day: number): CalendarDate {
  const local = day - epochOffsetOf(def);
  const a = yearIndexOf(def, local);
  const dayOfYear = local - daysBeforeYear(def, a);

  const eraIndex = eraIndexFor(def, day);
  const era = def.eras[eraIndex];
  const year = a - eraStartYearIndex(def, eraIndex) + 1;

  // Walk the months until the day-of-year falls inside one.
  let remaining = dayOfYear;
  let monthIndex = 0;
  for (let i = 0; i < def.months.length; i++) {
    monthIndex = i;
    const length = daysInMonth(def, a, i + 1);
    if (remaining < length) break;
    remaining -= length;
  }

  const weekdayCount = def.weekdays.length;
  return {
    eraIndex,
    eraName: era?.name ?? "",
    year,
    month: monthIndex + 1,
    monthName: def.months[monthIndex]?.name ?? "",
    day: remaining + 1,
    weekday: weekdayCount > 0 ? (def.weekdays[euclidMod(local, weekdayCount)] ?? null) : null,
  };
}

/**
 * Calendar parts -> absolute day number (the inverse of `toDate`). `month` and
 * `day` are 1-based. Does not check that the day exists (see `daysInMonth`).
 */
export function fromDate(
  def: CalendarDefinition,
  eraIndex: number,
  year: number,
  month: number,
  day: number,
): number {
  const a = yearIndexFor(def, eraIndex, year);
  return startOfMonth(def, a, month - 1) + (day - 1);
}

/** Formats a day number in one of the backend's `DateStyle`s. */
export function formatDate(def: CalendarDefinition, day: number, style: DateStyle): string {
  return formatParts(def, toDate(def, day), style);
}

export function formatParts(def: CalendarDefinition, p: CalendarDate, style: DateStyle): string {
  const era = eraLabel(def, p.eraIndex);
  switch (style) {
    case "full":
      return `${p.day} ${p.monthName}, ${p.year} ${era}`.trim();
    case "short":
      return `${p.day}/${p.month}/${p.year} ${era}`.trim();
    case "monthYear":
      return `${p.monthName}, ${p.year} ${era}`.trim();
    case "year":
      return `${p.year} ${era}`.trim();
    case "month":
      return p.monthName;
    case "day":
      return String(p.day);
  }
}
